input.command:
python3 - <<'PY'
from pathlib import Path
p=Path('scripts/lib/importer-live-harness.ts'); s=p.read_text()
a=s.index("async function textProbe(step: number)")
b=s.index("\npenpot.ui.open(")
new='''async function textProbe(variant: number): Promise<Probe> {
  const out: Probe = { variant };
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(900, 600);
  const text = penpot.createText("Rotated heading text"); if (!text) throw new Error("text failed");
  // Variant 3 keeps the text at the page root; the others place it in a board.
  if (variant !== 3) host.appendChild(text);
  text.fontFamily = "Inter"; text.fontSize = "30"; text.fills = [{ fillColor: "#112233", fillOpacity: 1 }];
  text.growType = "fixed"; text.x = 450; text.y = 300; text.resize(262, 36);
  await new Promise((resolve) => setTimeout(resolve, 800));
  out.size = { x: text.x, y: text.y, width: text.width, height: text.height };
  if (variant === 1) { text.rotation = 20; }
  else if (variant === 2) { const group = penpot.group([text]); if (!group) throw new Error("group failed"); group.rotation = 20; out.group = describe(group); }
  else if (variant === 3) { text.rotation = 20; }
  else if (variant === 4) { text.rotate(20, { x: 450, y: 300 }); }
  out.rotated = describe(text);
  out.hostId = host.id;
  return out;
}
'''
s=s[:a]+new+s[b:]
p.write_text(s)
PY
npx tsc --noEmit 2>&1 | tail -3; node scripts/importer-live-harness.mjs >/dev/null; orca-ide tab close --page 2719f3da-fdc4-447d-bf15-6d4ce65eb686 --json 2>&1 | grep closed; orca-ide tab create --url "https://design.penpot.app/#/workspace?team-id=68a1c0e6-b27c-807b-8004-47211259833e&file-id=40e06342-8830-80d6-8008-9046d08f8400&page-id=40e06342-8830-80d6-8008-9046d08f8401" --json 2>&1 | grep browserPageId

