python3 - <<'PY'
from pathlib import Path
# 1. harness HTML: forward messages to an optional local log server
m=Path('scripts/importer-live-harness.mjs'); t=m.read_text()
t=t.replace('''addEventListener("message", event => {
  if (event.source !== parent) return;''','''// Optional progress log: this frame runs in its own process, so it can still report steps sent before the host tab stalls.
const logPort = new URLSearchParams(location.search).get("log");
const forward = value => { if (logPort) fetch("http://localhost:" + logPort + "/log", { method: "POST", mode: "no-cors", body: JSON.stringify(value) }).catch(() => {}); };
addEventListener("message", event => {
  if (event.source !== parent) return;
  forward(event.data);''',1)
t=t.replace("define: { LIVE_IMAGES:","define: { LOG_PORT: JSON.stringify(process.env.PHASE5_LOG_PORT || \"\"), LIVE_IMAGES:",1)
m.write_text(t)
# 2. harness entry
h=Path('scripts/lib/importer-live-harness.ts'); s=h.read_text()
s=s.replace("declare const LIVE_IMAGES: string[];","declare const LIVE_IMAGES: string[];\ndeclare const LOG_PORT: string;",1)
s=s.replace('penpot.ui.open("Importer host validation", "?phase5-validation",','penpot.ui.open("Importer host validation", LOG_PORT ? `?phase5-validation&log=${LOG_PORT}` : "?phase5-validation",',1)
# 3. text probe with step markers
a=s.index("async function textProbe(variant: number)")
b=s.index("\npenpot.ui.open(")
new='''async function textProbe(variant: number): Promise<Probe> {
  const out: Probe = { variant };
  const step = (name: string) => send({ type: "probe-step", variant, name });
  step("create-board");
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(900, 600);
  step("create-text");
  const text = penpot.createText("Rotated heading text"); if (!text) throw new Error("text failed");
  if (variant !== 3) { step("append"); host.appendChild(text); }
  step("font-family"); text.fontFamily = "Inter";
  step("font-size"); text.fontSize = "30";
  step("fills"); text.fills = [{ fillColor: "#112233", fillOpacity: 1 }];
  step("grow-type"); text.growType = "fixed";
  step("position"); text.x = 450; text.y = 300;
  step("resize"); text.resize(262, 36);
  step("wait"); await new Promise((resolve) => setTimeout(resolve, 800));
  step("read"); out.size = { x: text.x, y: text.y, width: text.width, height: text.height };
  if (variant === 1) { step("rotation-setter"); text.rotation = 20; }
  else if (variant === 2) { step("group"); const group = penpot.group([text]); if (!group) throw new Error("group failed"); step("group-rotation"); group.rotation = 20; out.group = describe(group); }
  else if (variant === 3) { step("root-rotation"); text.rotation = 20; }
  else if (variant === 4) { step("rotate-call"); text.rotate(20, { x: 450, y: 300 }); }
  step("describe"); out.rotated = describe(text);
  out.hostId = host.id;
  return out;
}
'''
s=s[:a]+new+s[b:]
h.write_text(s)
PY
npx tsc --noEmit 2>&1 | tail -3
cat > /tmp/claude-1000/log-server.mjs <<'EOF'
import { createServer } from "node:http";
import { appendFileSync, writeFileSync } from "node:fs";
writeFileSync("/tmp/claude-1000/probe.log", "");
createServer((req, res) => {
  let body = "";
  req.on("data", (chunk) => body += chunk);
  req.on("end", () => { appendFileSync("/tmp/claude-1000/probe.log", new Date().toISOString().slice(11,23) + " " + body.slice(0, 600) + "\n"); res.writeHead(204, { "access-control-allow-origin": "*" }); res.end(); });
}).listen(4174, "0.0.0.0");
EOF
(node /tmp/claude-1000/log-server.mjs > /dev/null 2>&1 &) ; sleep 1; curl -s -o /dev/null -w "%{http_code}\n" -X POST -d '{"ping":1}' http://localhost:4174/log; cat /tmp/claude-1000/probe.log

