input.command:
python3 - <<'PY'
from pathlib import Path
q=Path('scripts/importer-live-orca.mjs'); t=q.read_text()
t=t.replace('size: Number(args[0]) || 1','size: Number.isFinite(Number(args[0])) ? Number(args[0]) : 1',1)
q.write_text(t)
h=Path('scripts/lib/importer-live-harness.ts'); s=h.read_text()
a=s.index("async function textProbe(variant: number)")
b=s.index("\npenpot.ui.open(")
new='''async function textProbe(variant: number): Promise<Probe> {
  const out: Probe = { variant };
  const step = (name: string) => send({ type: "probe-step", variant, name });
  const pause = (milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds));
  step("create-board");
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(900, 600);
  step("create-text");
  const text = penpot.createText("Rotated heading text"); if (!text) throw new Error("text failed");
  if (variant === 10 || variant === 11) {
    // The importer's own order: style the detached text, then attach and place it.
    step("grow-type"); text.growType = "fixed";
    step("characters"); text.characters = "Rotated heading text";
    step("font-family"); text.fontFamily = "Inter";
    step("font-size"); text.fontSize = "30";
    step("fills"); text.fills = [{ fillColor: "#112233", fillOpacity: 1 }];
    step("append"); host.appendChild(text);
    step("position"); text.x = 450; text.y = 300;
    step("resize"); text.resize(262, 36);
  } else {
    step("append"); host.appendChild(text);
    if (variant === 13) { step("font-family"); text.fontFamily = "Inter"; }
    step("font-size"); text.fontSize = "30";
    if (variant === 12) { step("fills"); text.fills = [{ fillColor: "#112233", fillOpacity: 1 }]; }
    step("grow-type"); text.growType = "auto-width";
    step("position"); text.x = 450; text.y = 300;
  }
  step("wait"); await pause(800);
  step("read"); out.size = { x: text.x, y: text.y, width: text.width, height: text.height };
  if (variant === 11) { step("rotation-setter"); text.rotation = 20; await pause(500); step("rotated"); out.rotated = describe(text); }
  step("done");
  out.hostId = host.id;
  return out;
}
'''
s=s[:a]+new+s[b:]
h.write_text(s)
PY
