input.command:
N=$(cat /tmp/claude-1000/tab); timeout 40 orca-ide screenshot --page $N --json > /tmp/claude-1000/hung.json 2>&1; head -c 300 /tmp/claude-1000/hung.json; python3 - <<'PY'
import json,base64
try:
    d=json.load(open('/tmp/claude-1000/hung.json'))
    r=d['result']
    data=r.get('data') or r.get('base64') or r.get('image')
    if data:
        open('/tmp/claude-1000/hung.png','wb').write(base64.b64decode(data)); print('saved')
    else: print(list(r.keys()))
except Exception as e: print('err',e)
PY

