input.command:
python3 - <<'PY'
from pathlib import Path
h=Path('scripts/lib/importer-live-harness.ts'); s=h.read_text()
a=s.index("async function textProbe(variant: number)")
b=s.index("\npenpot.ui.open(")
new='''async function textProbe(variant: number): Promise<Probe> {
  const out: Probe = { variant };
  const pause = (milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds));
  // Yield after each marker so it is delivered even if the next host call stalls the tab.
  const step = async (name: string) => { send({ type: "probe-step", variant, name }); await pause(40); };
  await step("create-board");
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(900, 600);
  let text: import("@penpot/plugin-types").Text | null;
  if (variant === 24) {
    // A text layer authored in the Penpot UI: clone one from the first page, then delete the clone.
    const original = penpot.currentFile?.pages[0]?.findShapes({ type: "text" })[0];
    if (!original) throw new Error("No existing text layer to clone.");
    await step("clone"); text = original.clone() as import("@penpot/plugin-types").Text;
    out.cloneId = text.id;
  } else {
    await step("create-text"); text = penpot.createText("Rotated heading text");
    if (!text) throw new Error("text failed");
    text.growType = "fixed"; text.fontFamily = "Inter"; text.fontSize = "30";
    text.fills = [{ fillColor: "#112233", fillOpacity: 1 }];
    if (variant !== 21) host.appendChild(text);
    text.x = 450; text.y = 300; text.resize(262, 36);
  }
  if (variant !== 22) { await step("wait"); await pause(800); }
  await step("rotation-setter"); text.rotation = 20;
  await pause(500); await step("rotated"); out.rotated = describe(text);
  if (variant === 24) text.remove();
  await step("done");
  out.hostId = host.id;
  return out;
}
'''
s=s[:a]+new+s[b:]
h.write_text(s)
PY
npx tsc --noEmit 2>&1 | tail -3; PHASE5_LOG_PORT=4174 node scripts/importer-live-harness.mjs >/dev/null
cat > /tmp/claude-1000/runvariants.sh <<'EOF'
#!/bin/bash
# usage: runvariants.sh v1 v2 ...  (one fresh tab per variant; closes it afterwards)
cd /home/peterc/ultimate-html-penpot-ext
URL="https://design.penpot.app/#/workspace?team-id=68a1c0e6-b27c-807b-8004-47211259833e&file-id=40e06342-8830-80d6-8008-9046d08f8400&page-id=40e06342-8830-80d6-8008-9046d08f8401"
for v in "$@"; do
  N=$(orca-ide tab create --url "$URL" --json | python3 -c "import json,sys;print(json.load(sys.stdin)['result']['browserPageId'])")
  sleep 8
  timeout 150 node scripts/importer-live-orca.mjs $N open >/dev/null 2>&1 || { echo "open failed"; orca-ide tab close --page $N --json >/dev/null; continue; }
  : > /tmp/claude-1000/probe.log
  node scripts/importer-live-orca.mjs $N text-probe $v >/dev/null 2>&1
  ok=0
  for i in $(seq 1 30); do sleep 1; if grep -q '"type":"text-probe"' /tmp/claude-1000/probe.log; then ok=1; break; fi; done
  last=$(grep -o '"name":"[a-z-]*"' /tmp/claude-1000/probe.log | tail -1)
  echo "variant $v ok=$ok last=$last"
  [ $ok = 1 ] && grep '"type":"text-probe"' /tmp/claude-1000/probe.log | cut -c1-500
  timeout 20 orca-ide tab close --page $N --json >/dev/null 2>&1
done
EOF
chmod +x /tmp/claude-1000/runvariants.sh; orca-ide tab close --page $(cat /tmp/claude-1000/tab) --json 2>&1 | grep -c closed; /tmp/claude-1000/runvariants.sh 21 22

