input.command:
PID=$(ss -ltnp 2>/dev/null | grep ':4174' | grep -o 'pid=[0-9]*' | head -1 | cut -d= -f2); [ -n "$PID" ] && kill $PID; sed -i 's/body.slice(0, 600)/body.slice(0, 6000)/' /tmp/claude-1000/log-server.mjs; sed -i 's/cut -c1-500/cut -c1-6000/' /tmp/claude-1000/runvariants.sh; sleep 1; (node /tmp/claude-1000/log-server.mjs > /dev/null 2>&1 &); sleep 1; grep -c 6000 /tmp/claude-1000/log-server.mjs; /tmp/claude-1000/runvariants.sh 33 >/dev/null 2>&1; python3 - <<'PY'
import json
for line in open('/tmp/claude-1000/probe.log'):
    if '"type":"text-probe"' in line:
        j=json.loads(line[line.index('{'):])
        for k,v in j['result'].items(): print(k, json.dumps(v))
PY

