  #outer-clip { width: 200px; height: 70px; overflow: hidden; background: #dcfce7; border: 2px solid #16a34a; }
  #inner-clip { width: 260px; height: 30px; margin: 8px; overflow: hidden; background: #bbf7d0; border: 2px solid #15803d; }

