cd /home/peterc/.claude/projects/-home-peterc-ultimate-html-penpot-ext && python3 - <<'PY'
import json,re
msgs=[]
with open('b2ec2cfa-18e5-4212-bfd7-af18aaa59d48.jsonl') as f:
    for line in f:
        try: msgs.append(json.loads(line))
        except: pass
idx=[i for i,d in enumerate(msgs) if 'page-delete-btn' in json.dumps(d) and d.get('type')=='assistant']
print(len(idx), idx[:5])
start=idx[0]
for d in msgs[start:start+14]:
    c=d.get('message',{}).get('content')
    if isinstance(c,str): print(d['type'],'TEXT',c[:600]); continue
    for part in c or []:
        if part.get('type')=='tool_use': print('TOOL_USE', json.dumps(part['input'])[:1500])
        elif part.get('type')=='tool_result':
            cc=part.get('content'); print('RESULT', (json.dumps(cc) if not isinstance(cc,str) else cc)[:700])
        elif part.get('type')=='text': print('TEXT', part['text'][:400])
    print('---')
PY

