python3 - <<'PY'
from pathlib import Path
h=Path('scripts/lib/importer-live-harness.ts'); s=h.read_text()
start=s.index('/** Shapes rotated well after creation')
end=s.index('penpot.ui.open(')
late='''/** Shapes rotated well after creation, as uploads and conversions delay some layers. Text is left out on purpose:
 * rotating a laid-out text layer stalls the host tab (see docs/importer-transforms.md). Each shape is read back
 * right after the rotation and again once the host has settled, next to a control rotated at creation. */
async function lateRotationProbe(): Promise<Probe> {
  const out: Probe = {};
  const pause = (milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds));
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(900, 600);
  const rect = (x: number, y: number) => {
    const value = penpot.createRectangle(); host.appendChild(value); value.x = x; value.y = y; value.resize(262, 36); return value;
  };
  const control = rect(150, 150); control.rotation = 20; out.controlImmediate = describe(control);
  const late = rect(150, 250);
  const svg = penpot.createShapeFromSvg('<svg xmlns="http://www.w3.org/2000/svg" width="120" height="60"><rect width="120" height="60" fill="#c33"/><circle cx="30" cy="30" r="20" fill="#fff"/></svg>');
  if (!svg) throw new Error("svg failed");
  host.appendChild(svg); svg.x = 500; svg.y = 150;
  const clip = penpot.createBoard(); host.appendChild(clip); clip.x = 150; clip.y = 350; clip.resize(262, 100); clip.clipContent = true;
  await pause(1200);
  late.rotation = 20; svg.rotation = 20; clip.rotation = 20;
  out.lateImmediate = { rect: describe(late), svgGroup: describe(svg), clipBoard: describe(clip) };
  await pause(500);
  out.lateSettled = { rect: describe(late), svgGroup: describe(svg), clipBoard: describe(clip) };
  out.controlSettled = describe(control);
  out.hostId = host.id;
  return out;
}

'''
s=s[:start]+late+s[end:]
h.write_text(s)
PY
npx tsc --noEmit 2>&1 | tail -3; node scripts/importer-live-harness.mjs | tail -1 && N=$(cat /tmp/claude-1000/tab) && timeout 150 node scripts/importer-live-orca.mjs $N open >/dev/null 2>&1; node scripts/importer-live-orca.mjs $N late-rotation-probe && sleep 8 && node scripts/importer-live-orca.mjs $N status | python3 -c "
