d=json.load(sys.stdin); l=d['last']; print(l['type'])
r=l['result']
def short(v): return (v['x'],v['y'],v['width'],v['height'],v['rotation'],'c',v['center']['x'],v['center']['y'],'b',v['bounds']['x'],v['bounds']['y'],v['bounds']['width'],v['bounds']['height'])
print('controlImmediate', short(r['controlImmediate']))
print('controlSettled  ', short(r['controlSettled']))
for k in ('lateImmediate','lateSettled'):
    for n,v in r[k].items(): print(k,n,short(v))"

