input.command:
python3 - <<'PY'
from pathlib import Path
m=Path('scripts/importer-live-harness.mjs'); t=m.read_text()
old='''const fixtureScenes = evidence.fixtures.find((fixture) => fixture.file === fixtureFile)?.viewports.map((viewport) => viewport.scene) ?? [];
'''
new='''const mediaTypes = { ".svg": "image/svg+xml", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".gif": "image/gif", ".webp": "image/webp" };
// The baselines captured assets from a local fixture server; inline them so the host pass needs no server.
async function inlineFixtureAsset(asset) {
  const name = asset.url && new URL(asset.url).pathname.split("/").pop();
  const type = name && mediaTypes[extname(name)];
  if (!type) return asset;
  try { return { id: asset.id, dataUrl: `data:${type};base64,${(await readFile(resolve("src/capture/fixtures/assets", name))).toString("base64")}`, mimeType: type }; }
  catch { return asset; }
}
const fixtureScenes = await Promise.all((evidence.fixtures.find((fixture) => fixture.file === fixtureFile)?.viewports ?? [])
  .map(async ({ scene }) => ({ ...scene, assets: await Promise.all(scene.assets.map(inlineFixtureAsset)) })));
'''
assert old in t
t=t.replace(old,new,1)
t=t.replace('import { resolve } from "node:path";','import { extname, resolve } from "node:path";',1)
m.write_text(t)
PY
node scripts/importer-live-harness.mjs | tail -1 && grep -c "data:image/svg+xml;base64" dist/plugin.js
orca-ide tab list --json | python3 -c "import json,sys;print(json.load(sys.stdin)['result'])" | head -20

