1	import { afterEach, describe, expect, it } from "vitest";
2	import type { SceneDocument, SceneNode, ViewportSpec } from "../shared/contracts";
3	import { buildExtractorScript } from "./extractor";
4	
5	const VIEWPORT: ViewportSpec = { id: "test", name: "Test", width: 400, height: 300 };
6	const IDENTITY = "matrix(1, 0, 0, 1, 0, 0)";
7	
8	interface Box { x: number; y: number; width: number; height: number }
9	/** Computed values this double reports for an element; jsdom does not derive them from the cascade. */
10	type Declared = Record<string, string>;
11	
12	const toRect = ({ x, y, width, height }: Box) => ({ x, y, left: x, top: y, right: x + width, bottom: y + height, width, height, toJSON: () => ({}) });
13	
14	function rotation(degrees: number): string {
15	  const radians = degrees * Math.PI / 180;
16	  const cos = Math.cos(radians).toFixed(6);
17	  const sin = Math.sin(radians).toFixed(6);
18	  return `matrix(${cos}, ${sin}, ${(-Number(sin)).toFixed(6)}, ${cos}, 0, 0)`;
19	}
20	
21	function captureScript(token: string): Promise<SceneDocument> {
22	  return new Promise((resolve, reject) => {
23	    const cleanup = () => { window.removeEventListener("message", receive); window.clearTimeout(timeout); };
24	    const receive = (event: MessageEvent) => {
25	      if (event.data?.token !== token) return;
26	      cleanup();
27	      if (event.data.type === "CAPTURE_RESULT") resolve(event.data.scene as SceneDocument);
28	      else reject(new Error(event.data.message || "Capture failed."));
29	    };
30	    const timeout = window.setTimeout(() => { cleanup(); reject(new Error(`Capture ${token} did not complete.`)); }, 5_000);
31	    window.addEventListener("message", receive);
32	    try { window.eval(buildExtractorScript(token, VIEWPORT, 0)); } catch (error) { cleanup(); reject(error); }
33	  });
34	}
35	
36	/**
37	 * A browser double for transform capture. An element reports its layout box
38	 * unless it still carries a declared transform, in which case it reports the
39	 * configured transformed bounds, exactly as a browser reports the bounding box
40	 * of a transformed element. Capture neutralizes supported transforms with an
41	 * identity matrix, which is what makes the layout box visible.
42	 */
43	function installBrowser(layout: Record<string, Box>, declared: Record<string, Declared> = {}, visual: Record<string, Box> = {}, line?: Box): () => void {
44	  const originalBounds = HTMLElement.prototype.getBoundingClientRect;
45	  const originalComputedStyle = window.getComputedStyle;
46	  const originalCreateRange = document.createRange;
47	  const originalCss = window.CSS;
48	  const identify = (element: Element) => element.id || (element === document.body ? "body" : "");
49	  HTMLElement.prototype.getBoundingClientRect = function () {
50	    const id = identify(this);
51	    const neutral = this.style.getPropertyValue("transform") === IDENTITY;
52	    const transformed = Boolean(declared[id]) && !neutral && visual[id];
53	    return toRect(transformed ? visual[id] : layout[id] ?? { x: 0, y: 0, width: 0, height: 0 });
54	  };
55	  window.getComputedStyle = ((element: Element, pseudo?: string | null) => {
56	    const style = Object.create(originalComputedStyle.call(window, element)) as CSSStyleDeclaration;
57	    const overrides = pseudo ? undefined : declared[identify(element)];
58	    for (const [name, value] of Object.entries(overrides ?? {})) Object.defineProperty(style, name, { value, configurable: true });
59	    return style;
60	  }) as typeof window.getComputedStyle;
61	  document.createRange = (() => ({
62	    selectNodeContents: () => undefined, setStart: () => undefined, setEnd: () => undefined,
63	    getClientRects: () => (line ? [toRect(line)] : []), getBoundingClientRect: () => toRect(line ?? { x: 0, y: 0, width: 0, height: 0 })
64	  })) as unknown as typeof document.createRange;
65	  Object.defineProperty(window, "CSS", { value: { escape: (value: string) => value }, configurable: true });
66	  return () => {
67	    HTMLElement.prototype.getBoundingClientRect = originalBounds;
68	    window.getComputedStyle = originalComputedStyle;
69	    document.createRange = originalCreateRange;
70	    Object.defineProperty(window, "CSS", { value: originalCss, configurable: true });
71	  };
72	}
73	
74	const VISIBLE = "opacity:1;visibility:visible";
75	const bySource = (scene: SceneDocument, source: string): SceneNode => {
76	  const node = scene.nodes.find((candidate) => candidate.source === source);
77	  if (!node) throw new Error(`Missing scene node ${source}.`);
78	  return node;
79	};
80	
81	describe("extractor transforms", () => {
82	  let restore: (() => void) | undefined;
83	  afterEach(() => { restore?.(); restore = undefined; });
84	
85	  it("keeps a rotated layer's own size and moves its corner to the rotated position", async () => {
86	    document.body.innerHTML = `<div id="card" style="${VISIBLE}"></div>`;
87	    document.body.style.cssText = VISIBLE;
88	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, card: { x: 100, y: 50, width: 100, height: 40 } },
89	      { card: { transform: rotation(90), transformOrigin: "50px 20px" } },
90	      { card: { x: 130, y: 20, width: 40, height: 100 } });
91	    const scene = await captureScript("rotated");
92	    const card = bySource(scene, "#card");
93	    // The center (150, 70) is fixed; the top-left corner turns clockwise to (170, 20).
94	    expect(card.rect).toEqual({ x: 170, y: 20, width: 100, height: 40 });
95	    expect(card.rotation).toBe(90);
96	    expect((document.querySelector("#card") as HTMLElement).style.getPropertyValue("transform")).toBe(IDENTITY);
97	    expect(scene.diagnostics.filter((diagnostic) => diagnostic.code === "UNSUPPORTED_TRANSFORM")).toEqual([]);
98	  });
99	
100	  it("moves text lines with the rotated element that contains them", async () => {
101	    document.body.innerHTML = `<div id="card" style="${VISIBLE}">Hello</div>`;
102	    document.body.style.cssText = VISIBLE;
103	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, card: { x: 100, y: 50, width: 100, height: 40 } },
104	      { card: { transform: rotation(90), transformOrigin: "50px 20px" } }, {}, { x: 102, y: 52, width: 40, height: 12 });
105	    const scene = await captureScript("rotated-text");
106	    const text = scene.nodes.find((node) => node.kind === "text");
107	    expect(text?.rect).toEqual({ x: 168, y: 22, width: 40, height: 12 });
108	    expect(text?.rotation).toBe(90);
109	  });
110	
111	  it("applies translation and uniform scale to boxes, text, borders, and radii", async () => {
112	    document.body.innerHTML = `<div id="zoom" style="${VISIBLE};font-size:10px;border:2px solid rgb(1, 2, 3)">Hi</div>`;
113	    document.body.style.cssText = VISIBLE;
114	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, zoom: { x: 20, y: 10, width: 30, height: 10 } },
115	      { zoom: { transform: "matrix(2, 0, 0, 2, 10, 5)", transformOrigin: "0px 0px", borderTopLeftRadius: "4px", borderTopRightRadius: "4px", borderBottomRightRadius: "4px", borderBottomLeftRadius: "4px" } }, {}, { x: 22, y: 12, width: 12, height: 8 });
116	    const scene = await captureScript("scaled");
117	    const zoom = bySource(scene, "#zoom");
118	    expect(zoom.rect).toEqual({ x: 30, y: 15, width: 60, height: 20 });
119	    expect(zoom.rotation).toBeUndefined();
120	    expect(zoom.paint.borderWidth).toBe(4);
121	    expect(zoom.paint.radius).toEqual([8, 8, 8, 8]);
122	    const text = scene.nodes.find((node) => node.kind === "text");
123	    expect(text?.rect).toEqual({ x: 34, y: 19, width: 24, height: 16 });
124	    expect(text?.textStyle?.fontSize).toBe(20);
125	  });
126	
127	  it("composes nested rotations in layout space", async () => {
128	    document.body.innerHTML = `<div id="outer" style="${VISIBLE}"><div id="inner" style="${VISIBLE}"></div></div>`;
129	    document.body.style.cssText = VISIBLE;
130	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, outer: { x: 0, y: 0, width: 200, height: 100 }, inner: { x: 20, y: 20, width: 60, height: 20 } },
131	      { outer: { transform: rotation(10), transformOrigin: "100px 50px" }, inner: { transform: rotation(20), transformOrigin: "30px 10px" } });
132	    const scene = await captureScript("nested");
133	    expect(bySource(scene, "#outer").rotation).toBe(10);
134	    const inner = bySource(scene, "#inner");
135	    expect(inner.rotation).toBe(30);
136	    expect(inner.rect.width).toBe(60);
137	    expect(inner.rect.height).toBe(20);
138	    // The inner center (50, 30) is turned 10 degrees about the outer center (100, 50).
139	    const radians = 10 * Math.PI / 180;
140	    const center = { x: 100 + (50 - 100) * Math.cos(radians) - (30 - 50) * Math.sin(radians), y: 50 + (50 - 100) * Math.sin(radians) + (30 - 50) * Math.cos(radians) };
141	    const corner = { x: center.x + (-30 * Math.cos(30 * Math.PI / 180) + 10 * Math.sin(30 * Math.PI / 180)), y: center.y + (-30 * Math.sin(30 * Math.PI / 180) - 10 * Math.cos(30 * Math.PI / 180)) };
142	    expect(inner.rect.x).toBeCloseTo(corner.x, 1);
143	    expect(inner.rect.y).toBeCloseTo(corner.y, 1);
144	  });
145	
146	  it("composes the translate, rotate, and scale properties before transform", async () => {
147	    document.body.innerHTML = `<div id="props" style="${VISIBLE}"></div>`;
148	    document.body.style.cssText = VISIBLE;
149	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, props: { x: 0, y: 0, width: 10, height: 6 } },
150	      { props: { translate: "8px 4px", rotate: "90deg", scale: "2", transformOrigin: "5px 3px" } });
151	    const props = bySource(await captureScript("properties"), "#props");
152	    expect(props.rect.x).toBeCloseTo(19, 5);
153	    expect(props.rect.y).toBeCloseTo(-3, 5);
154	    expect(props.rect.width).toBe(20);
155	    expect(props.rect.height).toBe(12);
156	    expect(props.rotation).toBe(90);
157	  });
158	
159	  it.each([
160	    ["skew", "matrix(1, 0, 0.36397, 1, 0, 0)"],
161	    ["non-uniform scale", "matrix(2, 0, 0, 1, 0, 0)"],
162	    ["mirror", "matrix(-1, 0, 0, 1, 0, 0)"],
163	    ["3D rotation", "matrix3d(1, 0, 0, 0, 0, 0.8, 0.6, 0, 0, -0.6, 0.8, 0, 0, 0, 0, 1)"]
164	  ])("keeps the transformed bounds of an element with a %s and reports it", async (_name, transform) => {
165	    document.body.innerHTML = `<div id="odd" style="${VISIBLE}"><div id="child" style="${VISIBLE}"></div></div>`;
166	    document.body.style.cssText = VISIBLE;
167	    restore = installBrowser({ body: { x: 0, y: 0, width: 400, height: 300 }, odd: { x: 10, y: 10, width: 100, height: 40 }, child: { x: 10, y: 10, width: 20, height: 10 } },
168	      { odd: { transform, transformOrigin: "50px 20px" } },
169	      { odd: { x: 5, y: 8, width: 130, height: 44 }, child: { x: 6, y: 9, width: 24, height: 12 } });
170	    const scene = await captureScript("unsupported");
171	    expect(bySource(scene, "#odd").rect).toEqual({ x: 5, y: 8, width: 130, height: 44 });
172	    expect(bySource(scene, "#odd").rotation).toBeUndefined();
173	    expect((document.querySelector("#odd") as HTMLElement).style.getPropertyValue("transform")).toBe("");
