python3 - <<'PY'
from pathlib import Path
h=Path('scripts/lib/importer-live-harness.ts'); s=h.read_text()
marker='penpot.ui.open('
probe='''/** How long after creation can a rectangle still be rotated and then placed the way the importer does it? */
async function delaySweepProbe(): Promise<Probe> {
  const out: Probe = {};
  const pause = (milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds));
  const host = penpot.createBoard(); host.x = 100; host.y = 100; host.resize(1000, 800);
  const rows: Probe[] = [];
  for (const [index, delay] of [0, 25, 50, 100, 200, 400, 800, 1600].entries()) {
    const value = penpot.createRectangle(); host.appendChild(value);
    const corner = { x: 150, y: 120 + index * 80 };
    value.x = corner.x; value.y = corner.y; value.resize(200, 40);
    if (delay) await pause(delay);
    value.rotation = 20;
    const want = rotatedBoundsOrigin(corner, 200, 40, 20);
    value.x = want.x; value.y = want.y;
    await pause(300);
    rows.push({ delay, want: { x: round(want.x), y: round(want.y) }, ...describe(value) });
  }
  out.rows = rows; out.hostId = host.id;
  return out;
}

'''
i=s.index(marker)
s=s[:i]+probe+s[i:]
old='''    } else if (message.action === "inspect") {'''
new='''    } else if (message.action === "delay-probe") {
      const page = penpot.createPage();
      page.name = `${pagePrefix}delay probe`;
      await openPage(page);
      send({ type: "delay-probe", pageId: page.id, result: await delaySweepProbe() });
    } else if (message.action === "inspect") {'''
assert old in s
s=s.replace(old,new,1)
h.write_text(s)
q=Path('scripts/importer-live-orca.mjs'); u=q.read_text()
u=u.replace('''} else if (action === "rotated-image") {''','''} else if (action === "delay-probe") {
  console.log(send({ action: "delay-probe" }));
} else if (action === "rotated-image") {''',1)
u=u.replace('|late-rotation-probe|','|late-rotation-probe|delay-probe|',1)
q.write_text(u)
PY
npx tsc --noEmit 2>&1 | tail -3; node scripts/importer-live-harness.mjs | tail -1
