# 3b. backdrop path
old='''            const backdrop = needsContainerBackdrop(node) ? await createContainerBackdrop(node, assets, media, track) : undefined;
            throwIfCancelled();
            if (backdrop) {
              metadata(backdrop, node, scene.viewport.id);
              reportAssetFallback(backdrop, node, node.assetId ? assets.get(node.assetId) : undefined, scene.viewport.id, options);
