70	  const number = (value) => { const parsed = parseFloat(value || "0"); return Number.isFinite(parsed) ? parsed : 0; };
71	  const compact = (value) => String(value || "").replace(/\\s+/g, " ").trim();
72	  const rectOf = (rect) => ({ x: Math.round(rect.x * 100) / 100, y: Math.round(rect.y * 100) / 100, width: Math.round(rect.width * 100) / 100, height: Math.round(rect.height * 100) / 100 });
73	  // CSS transforms. A transformed element's own transform is recorded and
74	  // replaced by an identity matrix before its box is read, so that element and
75	  // every descendant are measured in untransformed layout space. The recorded
76	  // matrices are composed into a frame for each node: its own size, the
77	  // position of its top-left corner after all transforms, and a rotation about
78	  // that corner. Penpot rotates a layer from its own unrotated size, so
79	  // rotating a transformed bounding box would grow and displace the layer.
80	  const IDENTITY = [1, 0, 0, 1, 0, 0];
81	  const matrices = new Map();
82	  const compose = (outer, inner) => [
83	    outer[0] * inner[0] + outer[2] * inner[1], outer[1] * inner[0] + outer[3] * inner[1],
84	    outer[0] * inner[2] + outer[2] * inner[3], outer[1] * inner[2] + outer[3] * inner[3],
85	    outer[0] * inner[4] + outer[2] * inner[5] + outer[4], outer[1] * inner[4] + outer[3] * inner[5] + outer[5]
86	  ];
87	  const tokensOf = (value) => String(value || "").trim().split(/\\s+/).filter(Boolean);
88	  const angleDegrees = (token) => {
89	    const match = /^([+-]?(?:\\d+\\.?\\d*|\\.\\d+)(?:e[+-]?\\d+)?)(deg|grad|rad|turn)$/i.exec(token || "");
90	    if (!match) return undefined;
91	    const amount = parseFloat(match[1]);
92	    const unit = match[2].toLowerCase();
93	    return unit === "deg" ? amount : unit === "grad" ? amount * 0.9 : unit === "rad" ? amount * 180 / Math.PI : amount * 360;
94	  };
95	  const isSet = (value) => Boolean(value) && value !== "none";
96	  // Computed transforms serialize as matrix() or matrix3d(); the 3D form is
97	  // flat only when every component outside the 2D plane is the identity.
98	  const parseMatrix = (value) => {
99	    const match = /^matrix(3d)?\\(([^)]*)\\)$/.exec(String(value).trim());
100	    if (!match) return undefined;
101	    const values = match[2].split(",").map(parseFloat);
102	    if (values.some((entry) => !Number.isFinite(entry))) return undefined;
103	    if (!match[1]) return values.length === 6 ? { matrix: values, flat: true } : undefined;
104	    if (values.length !== 16) return undefined;
105	    const flat = [2, 3, 6, 7, 8, 9, 11, 14].every((index) => values[index] === 0) && values[10] === 1 && values[15] === 1;
106	    return { matrix: [values[0], values[1], values[4], values[5], values[12], values[13]], flat };
107	  };
108	  // CSS applies translate, then rotate, then scale, then transform. The result
109	  // is flat only when none of them has a 3D component.
110	  const readTransform = (style) => {
111	    if (!isSet(style.transform) && !isSet(style.translate) && !isSet(style.rotate) && !isSet(style.scale)) return undefined;
112	    let matrix = IDENTITY;
113	    let flat = true;
114	    // The computed translate property keeps percentages, which refer to the
115	    // layer's own box and are resolved once that box has been measured.
116	    let percent;
117	    if (isSet(style.translate)) {
118	      const [x = "0", y = "0", z = "0"] = tokensOf(style.translate);
119	      const parts = [x, y, z].map((token) => /^([+-]?(?:\\d+\\.?\\d*|\\.\\d+)(?:e[+-]?\\d+)?)(px|%)?$/i.exec(token));
120	      if (parts.some((part) => !part) || parseFloat(z)) flat = false;
121	      else {
122	        const [lengthX, lengthY] = parts.map((part, index) => index < 2 && part[2] !== "%" ? parseFloat(part[1]) : 0);
123	        const [percentX, percentY] = parts.map((part, index) => index < 2 && part[2] === "%" ? parseFloat(part[1]) : 0);
124	        matrix = compose(matrix, [1, 0, 0, 1, lengthX, lengthY]);
125	        if (percentX || percentY) percent = [percentX, percentY];
126	      }
127	    }
128	    if (isSet(style.rotate)) {
129	      const tokens = tokensOf(style.rotate);
130	      const degrees = tokens.length === 1 ? angleDegrees(tokens[0]) : undefined;
131	      if (degrees === undefined) flat = false;
132	      else {
133	        const radians = degrees * Math.PI / 180;
134	        matrix = compose(matrix, [Math.cos(radians), Math.sin(radians), -Math.sin(radians), Math.cos(radians), 0, 0]);
135	      }
136	    }
